// Фирменные цвета (official hex из simple-icons). Панель бывает тёмной И светлой, поэтому
// цвета с плохим контрастом в одной из тем НЕ задаём — они фолбэкнут на currentColor и
// подстроятся под тему: near-чёрные (Kafka #231F20, Elasticsearch #005571, VictoriaMetrics
// #621773) и жёлтые (ClickHouse #FFCC01, Vault #FFEC6E — тонут на белом).
const ENGINE_COLOR: Record<string, string> = {
  PostgreSQL: '#4169E1',
  'MySQL/MariaDB': '#4479A1',
  MongoDB: '#47A248',
  Redis: '#FF4438',
  RabbitMQ: '#FF6600',
  InfluxDB: '#22ADF6',
  Prometheus: '#E6522C',
  Grafana: '#F46800',
  etcd: '#419EDA',
  CockroachDB: '#6933FF',
  Neo4j: '#4581C3',
  CouchDB: '#E42528',
  MinIO: '#C72E49',
  Consul: '#F24C53',
  kubernetes: '#326CE5',
  HAProxy: '#169BD6',
  Qdrant: '#DC244C',
  Cassandra: '#1287B1',
  SurrealDB: '#FF00A0',
  vLLM: '#30A2FF',
  // веб-серверы / прокси
  nginx: '#009639',
  'ingress-nginx': '#009639',
  Envoy: '#AC6199',
  Traefik: '#24A1C1',
  Caddy: '#1F88C0',
  Apache: '#D22128',
  GitLab: '#FC6D26',
}

export function hasEngineIcon(name: string) {
  const brand = ENGINE_ALIAS[name] ?? name
  return !!(ENGINE_ASSET[brand] || ENGINE_PATH[brand])
}

export function EngineIcon({ name, size = 15 }: { name: string; size?: number }) {
  const brand = ENGINE_ALIAS[name] ?? name
  if (brand === 'LiteLLM') return <>
    <img className="engine-ico engine-theme-light" src={litellm} width={size} height={size} alt={name} title={name} />
    <img className="engine-ico engine-theme-dark" src={litellmDark} width={size} height={size} alt={name} title={name} />
  </>
  const asset = ENGINE_ASSET[brand]
  if (asset) return <img className="engine-ico" src={asset} width={size} height={size} alt={name} title={name} />
  const d = ENGINE_PATH[brand]
  if (!d) return null
  return (
    <svg className="engine-ico" viewBox="0 0 24 24" width={size} height={size}
      role="img" aria-label={name} focusable="false">
      <title>{name}</title>
      <path fill={ENGINE_COLOR[brand] ?? 'currentColor'} d={d} />
    </svg>
  )
}
